SELECT c.id, '2개의 미뉴에트 D. 91', '2 Minuets, D. 91', 'album', NULL, 'D.', '91', 1813, 'manual', 1
FROM composers c
WHERE c.id = 26
AND NOT EXISTS (
    SELECT 1 FROM pieces existing
    WHERE existing.composer_id = c.id AND existing.title = '2개의 미뉴에트 D. 91'
)
AND NOT EXISTS (
    SELECT 1 FROM piece_identifiers taken
    WHERE taken.namespace = 'musicbrainz_work' AND taken.external_id = 'b3716b79-cb1f-473a-bf4c-a3396ea5f875'
);

