SELECT p.id, NULL, NULL, 'musicbrainz:6ce4d1ce-4985-36a4-9e03-90df0bd3e4ba', 1, 'I', 'Adagio maestoso – Allegro con brio', 'I. Adagio maestoso - Allegro con brio', 'EDITOR_REVIEWED', 'manual', 1
FROM pieces p
WHERE p.id = 12602 AND p.composer_id = 26
AND NOT EXISTS (
    SELECT 1 FROM piece_parts existing
    WHERE existing.piece_id = p.id AND existing.part_key = 'musicbrainz:6ce4d1ce-4985-36a4-9e03-90df0bd3e4ba'
);

UPDATE piece_parts part
JOIN pieces p ON p.id = part.piece_id

SET part.parent_part_id = NULL,
    part.linked_piece_id = NULL,
    part.sequence_number = 2, part.movement_number = 'II',
    part.name_ko = 'Allegretto', part.name_en = 'II. Allegretto',
    part.editorial_status = 'EDITOR_REVIEWED', part.editor_locked = 1
WHERE p.id = 12602 AND p.composer_id = 26 AND part.part_key = 'musicbrainz:ef63f623-bd23-354a-bb71-886da1ac69d8' AND (part.editor_locked = 0 OR (part.origin = 'manual' AND part.editorial_status = 'FACTS_VERIFIED'));

