-- D. 257 가곡 <들장미 (Heidenröslein)>

INSERT INTO pieces
    (composer_id, title, title_en, type, opus_number, catalogue_system, catalogue_number, composition_year, origin, editor_locked)
SELECT c.id, '가곡 <들장미 (Heidenröslein)>', 'Heidenröslein', 'song', 'D. 257', NULL, NULL, 1815, 'manual', 1
FROM composers c
WHERE c.id = 26
AND NOT EXISTS (
    SELECT 1 FROM pieces existing
    WHERE existing.composer_id = c.id AND existing.title = '가곡 <들장미 (Heidenröslein)>'
)
AND NOT EXISTS (
    SELECT 1 FROM piece_identifiers taken
    WHERE taken.namespace = 'musicbrainz_work' AND taken.external_id = '43118055-589c-3764-9284-7f649f3b6d3e'
);

INSERT INTO piece_identifiers (piece_id, namespace, external_id)
SELECT p.id, 'musicbrainz_work', '43118055-589c-3764-9284-7f649f3b6d3e'
FROM pieces p
WHERE p.composer_id = 26 AND p.title = '가곡 <들장미 (Heidenröslein)>' AND p.origin = 'manual'
AND NOT EXISTS (
    SELECT 1 FROM piece_identifiers taken
    WHERE taken.namespace = 'musicbrainz_work' AND taken.external_id = '43118055-589c-3764-9284-7f649f3b6d3e'
);


