SELECT p.id, NULL, NULL, 'classicmap:schubert:schubert-d299:1', 1, NULL, '에코세즈', 'No. 1', 'EDITOR_REVIEWED', 'manual', 1
FROM pieces p
WHERE p.id = 12161 AND p.composer_id = 26
AND NOT EXISTS (
    SELECT 1 FROM piece_parts existing
    WHERE existing.piece_id = p.id AND existing.part_key = 'classicmap:schubert:schubert-d299:1'
);

