-- D. 300 가곡 <Der Jüngling an der Quelle>

UPDATE pieces piece
SET piece.title = '가곡 <Der Jüngling an der Quelle>', piece.title_en = 'Der Jüngling an der Quelle',
    piece.type = 'song', piece.opus_number = 'D. 300',
    piece.catalogue_system = NULL, piece.catalogue_number = NULL,
    piece.composition_year = COALESCE(1817, piece.composition_year),
    piece.editor_locked = 1
WHERE piece.id = 13426 AND piece.composer_id = 26
  AND piece.origin = 'seed' AND piece.editor_locked = 0;
UPDATE pieces piece
SET piece.composition_year = 1817
